from .facade import MTKMessageFacade


class mtk(object):

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self._facade = MTKMessageFacade()

    def setup(self, pyro_ip, pyro_port):
        """
        Setup pyro client

        :param str pyro_ip: server ip, used for creating pyro client
        :param int pyro_port: server port, used for creating pyro client
        :return: None
        """
        self._facade.setup(pyro_ip, pyro_port)

    def create_message_flow_alias(self, flow_alias, message_type, **kwargs):
        """
        Create a message flow and name it as alias

        :param str flow_alias: message flow alias name
        :param str message_type: message flow type which will be bound to this flow name,
                   supported ota_text, ota_json, system_trace, ps_trace, raw_string
        :param dict kwargs: additional configuration parameters which is used for subscribing log
        :return: None
        """
        self._facade.create_message_flow_alias(flow_alias, message_type, **kwargs)

    def expect_messages_in_flow(self, awaited_messages, flow_alias, timeout=3):
        """
        Declare expected message flow for messages defined in awaited_messages list.

        :param list awaited_messages: list of strings which define expected messages
        :param str flow_alias: message flow alias name
        :param int timeout: overall checking time seconds
        :return: None
        +---------------------+-----------------------------------------------+-------------------+
        |Example                                                                                  |
        +=====================+===============================================+===================+
        | expect_messages_in_flow                                             |                   |
        +---------------------+-----------------------------------------------+-------------------+
        | ...                 | UE_1:RRC_RRCConnectionRequest                 |                   |
        +---------------------+-----------------------------------------------+-------------------+
        | ...                 | UE_1:RRC_RRCConnectionSetup                   |                   |
        +---------------------+-----------------------------------------------+-------------------+
        | ...                 | UE_1:RRC_RRCConnectionSetupComplete           |                   |
        +---------------------+-----------------------------------------------+-------------------+
        | ...                 | MME_2:S1AP_InitialUEMessage                   |                   |
        +---------------------+-----------------------------------------------+-------------------+
        | ...                 | MME_2:S1AP_InitialContextSetupRequest         |                   |
        +---------------------+-----------------------------------------------+-------------------+
        | ...                 | UE_1:RRC_RRCConnectionReconfiguration         |                   |
        +---------------------+-----------------------------------------------+-------------------+
        | ...                 | UE_1:RRC_RRCConnectionReconfigurationComplete |                   |
        +---------------------+-----------------------------------------------+-------------------+
        | ...                 | flow_alias=ATTACH_FLOW                        | timeout=5         |
        +---------------------+-----------------------------------------------+-------------------+
        """
        self._facade.expect_messages_in_flow(awaited_messages, flow_alias, timeout)

    def get_latest_messages_in_flow(self, flow_alias, timeout=3):
        """
        Get latest messages from the flow which is specified by alias name

        :param str flow_alias: message flow alias name
        :param int timeout: overall checking time seconds
        :return: list of message string
        """
        return self._facade.get_latest_messages_in_flow(flow_alias, int(timeout))

    def teardown(self):
        pass
